  textPropertyKeys: mobile.keys,
  desktopSectionId: desktopSection.id,
  desktopDocFrameId: desktopDocs.id,
  desktopComponentSetId: desktop.set.id,
  desktopVariantIds: desktop.set.children.map((entry) => entry.id),
